{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.capsule_master_summary_tbl AS WITH capsule_skus AS ( SELECT DISTINCT UPPER(TRIM(SKU)) AS SKU_GROUP, TRIM(COLLECTION) AS CAPSULE FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 WHERE SKU IS NOT NULL AND COLLECTION IS NOT NULL ), sales_summary AS ( SELECT UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, c.CAPSULE AS CAPSULE, ANY_VALUE(h.CATEGORY) AS CATEGORY, SUM(h.GROSS_QUANTITY) AS TOTAL_QTY, SUM(h.GROSS_SALES) AS GROSS_SALES, SUM(h.DISCOUNT_AMOUNT) AS TOTAL_DISCOUNT, ROUND( SUM(h.GROSS_SALES) / NULLIF(SUM(h.GROSS_QUANTITY), 0), 2 ) AS ASP_GROSS FROM snitch_db.maplemonk.horizontal_sales_categories h JOIN capsule_skus c ON UPPER(TRIM(h.SKU_GROUP)) = UPPER(TRIM(c.SKU_GROUP)) GROUP BY UPPER(TRIM(h.SKU_GROUP)), c.CAPSULE ), images AS ( SELECT SKU_GROUP, IMAGE_URL FROM ( SELECT LEFT( variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION( \'-\' IN REVERSE(variant.value:sku::STRING) ) ) AS SKU_GROUP, image.value:\"preview\":\"image\":\"url\"::STRING AS IMAGE_URL, ROW_NUMBER() OVER ( PARTITION BY LEFT( variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION( \'-\' IN REVERSE(variant.value:sku::STRING) ) ) ORDER BY image.index, t.id ) AS RN FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN( input => PARSE_JSON(t.media) ) image, LATERAL FLATTEN( input => PARSE_JSON(t.variants) ) variant WHERE image.value:\"mediaContentType\"::STRING = \'IMAGE\' ) WHERE RN = 1 ), inventory AS ( SELECT UPPER(TRIM(i.SKU_GROUP)) AS SKU_GROUP, i.QTY_AVAILABLE AS WH_INVENTORY, i.QTY_OFFLINE_AVAILABLE AS STORE_INVENTORY FROM snitch_db.maplemonk.cogs_daily_snapshot i JOIN capsule_skus c ON UPPER(TRIM(i.SKU_GROUP)) = UPPER(TRIM(c.SKU_GROUP)) WHERE i.DATE = ( SELECT MAX(DATE) FROM snitch_db.maplemonk.cogs_daily_snapshot ) ), putaway_base AS ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX( \'-\', REVERSE(\"Item Type skuCode\") ) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS SKU_GROUP, \"PUTAWAY_UPDATED\"::DATE AS INWARD_DATE, SUM( \"PUTAWAY_COMPLETED_QUANTITY\" ) AS INWARD_QTY FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1, 2 ), inwards AS ( SELECT SKU_GROUP, MIN(INWARD_DATE) AS FIRST_INWARD_DATE, MAX(INWARD_DATE) AS LATEST_INWARD_DATE, SUM(INWARD_QTY) AS TOTAL_INWARD_QTY, COUNT(DISTINCT INWARD_DATE) AS INWARD_EVENTS, CASE WHEN COUNT(DISTINCT INWARD_DATE) > 1 THEN \'YES\' ELSE \'NO\' END AS REPEAT_ORDER FROM putaway_base GROUP BY SKU_GROUP ), mrp_map AS ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item SkuCode\"), POSITION( \'-\' IN REVERSE(\"Item SkuCode\") ) + 1 ) ) ) ) AS SKU_GROUP, MAX(MRP) AS MRP FROM snitch_db.maplemonk.snitch_final_inventory_wh2 GROUP BY 1 ), master_summary AS ( SELECT cs.SKU_GROUP, cs.CAPSULE, s.CATEGORY, img.IMAGE_URL, COALESCE( s.TOTAL_QTY, 0 ) AS TOTAL_QTY, COALESCE( s.GROSS_SALES, 0 ) AS GROSS_SALES, COALESCE( s.TOTAL_DISCOUNT, 0 ) AS TOTAL_DISCOUNT, COALESCE( s.ASP_GROSS, 0 ) AS ASP_GROSS, m.MRP, COALESCE( i.TOTAL_INWARD_QTY, 0 ) AS TOTAL_INWARD_QTY, i.FIRST_INWARD_DATE, i.LATEST_INWARD_DATE, COALESCE( i.INWARD_EVENTS, 0 ) AS INWARD_EVENTS, COALESCE( i.REPEAT_ORDER, \'NO\' ) AS REPEAT_ORDER, COALESCE( inv.WH_INVENTORY, 0 ) AS WH_INVENTORY, COALESCE( inv.STORE_INVENTORY, 0 ) AS STORE_INVENTORY, COALESCE( inv.WH_INVENTORY, 0 ) + COALESCE( inv.STORE_INVENTORY, 0 ) AS TOTAL_INVENTORY, COALESCE(m.MRP, 0) * COALESCE(i.TOTAL_INWARD_QTY, 0) AS OPENING_GMV, COALESCE(m.MRP, 0) * COALESCE(inv.WH_INVENTORY, 0) AS WH_INVENTORY_VALUE, COALESCE(m.MRP, 0) * COALESCE(inv.STORE_INVENTORY, 0) AS STORE_INVENTORY_VALUE, COALESCE(m.MRP, 0) * ( COALESCE(inv.WH_INVENTORY, 0) + COALESCE(inv.STORE_INVENTORY, 0) ) AS TOTAL_INVENTORY_VALUE, COALESCE(m.MRP, 0) * COALESCE(s.TOTAL_QTY, 0) AS SOLD_MERCHANDISE_VALUE FROM capsule_skus cs LEFT JOIN sales_summary s ON UPPER(TRIM(cs.SKU_GROUP)) = UPPER(TRIM(s.SKU_GROUP)) AND LOWER(TRIM(cs.CAPSULE)) = LOWER(TRIM(s.CAPSULE)) LEFT JOIN images img ON UPPER(TRIM(cs.SKU_GROUP)) = UPPER(TRIM(img.SKU_GROUP)) LEFT JOIN inventory inv ON UPPER(TRIM(cs.SKU_GROUP)) = UPPER(TRIM(inv.SKU_GROUP)) LEFT JOIN inwards i ON UPPER(TRIM(cs.SKU_GROUP)) = UPPER(TRIM(i.SKU_GROUP)) LEFT JOIN mrp_map m ON UPPER(TRIM(cs.SKU_GROUP)) = UPPER(TRIM(m.SKU_GROUP)) ), business_metrics AS ( SELECT m.*, ROUND( ( m.TOTAL_QTY / NULLIF( m.TOTAL_INWARD_QTY, 0 ) ) * 100, 2 ) AS STR_LIFETIME, DATEDIFF( DAY, m.FIRST_INWARD_DATE, CURRENT_DATE() ) + 1 AS DAYS_ACTIVE, ROUND( m.TOTAL_QTY / NULLIF( DATEDIFF( DAY, m.FIRST_INWARD_DATE, CURRENT_DATE() ) + 1, 0 ), 2 ) AS SALES_VELOCITY, ROUND( ( ( m.WH_INVENTORY + m.STORE_INVENTORY ) / NULLIF( m.TOTAL_INWARD_QTY, 0 ) ) * 100, 2 ) AS INVENTORY_REMAINING_PCT, ROUND( ( m.WH_INVENTORY + m.STORE_INVENTORY ) / NULLIF( m.TOTAL_QTY / NULLIF( DATEDIFF( DAY, m.FIRST_INWARD_DATE, CURRENT_DATE() ) + 1, 0 ), 0 ), 2 ) AS STOCK_COVER_DAYS, CASE WHEN m.REPEAT_ORDER = \'YES\' THEN 1 ELSE 0 END AS REPEAT_ORDER_FLAG FROM master_summary m ), online_customer_status AS ( SELECT c.CAPSULE AS CAPSULE, f.CUSTOMER_ID, MAX( CASE WHEN f.NEW_CUSTOMER_FLAG = \'New\' THEN 1 ELSE 0 END ) AS IS_NEW, MAX( CASE WHEN NVL( f.LOYALTY_CUSTOMER, \'NO\' ) = \'YES\' THEN 1 ELSE 0 END ) AS IS_LOYAL FROM snitch_db.maplemonk.fact_items_snitch f JOIN capsule_skus c ON UPPER(TRIM(f.SKU_GROUP)) = UPPER(TRIM(c.SKU_GROUP)) WHERE f.NEW_CUSTOMER_FLAG <> \'Yet to make completed order\' GROUP BY c.CAPSULE, f.CUSTOMER_ID ), online_customer_summary AS ( SELECT CAPSULE, COUNT( CASE WHEN IS_NEW = 1 THEN 1 END ) AS ONLINE_NEW_USERS, COUNT( CASE WHEN IS_NEW = 0 THEN 1 END ) AS ONLINE_REPEAT_USERS, COUNT( CASE WHEN IS_LOYAL = 1 THEN 1 END ) AS ONLINE_LOYAL_USERS, COUNT(*) AS ONLINE_TOTAL_USERS FROM online_customer_status GROUP BY CAPSULE ), offline_customer_status AS ( SELECT c.CAPSULE AS CAPSULE, REGEXP_REPLACE( f.PHONE, \'[^0-9]\', \'\' ) AS PHONE, CASE WHEN a.PHONE_NO IS NULL THEN NULL WHEN CAST( a.FIRST_ORDER_DATE AS DATE ) = CAST( f.ORDER_DATE AS DATE ) THEN 1 ELSE 0 END AS IS_NEW FROM snitch_db.maplemonk.store_fact_items_offline f JOIN capsule_skus c ON UPPER(TRIM(f.SKU_GROUP)) = UPPER(TRIM(c.SKU_GROUP)) LEFT JOIN snitch_db.maplemonk.customer_acq_date_channel a ON CAST( RIGHT( REGEXP_REPLACE( f.PHONE, \'[^0-9]\', \'\' ), 10 ) AS VARCHAR ) = CAST( RIGHT( REGEXP_REPLACE( a.PHONE_NO, \'[^0-9]\', \'\' ), 10 ) AS VARCHAR ) WHERE f.PHONE IS NOT NULL ), offline_customer_summary AS ( SELECT CAPSULE, COUNT( DISTINCT CASE WHEN IS_NEW = 1 THEN PHONE END ) AS OFFLINE_NEW_USERS, COUNT( DISTINCT CASE WHEN IS_NEW = 0 THEN PHONE END ) AS OFFLINE_REPEAT_USERS, COUNT( DISTINCT CASE WHEN IS_NEW IS NOT NULL THEN PHONE END ) AS OFFLINE_TOTAL_USERS FROM offline_customer_status GROUP BY CAPSULE ) SELECT bm.*, ocs.ONLINE_NEW_USERS, ocs.ONLINE_REPEAT_USERS, ocs.ONLINE_LOYAL_USERS, ocs.ONLINE_TOTAL_USERS, ROUND( ocs.ONLINE_REPEAT_USERS * 100.0 / NULLIF( ocs.ONLINE_TOTAL_USERS, 0 ), 2 ) AS ONLINE_REPEAT_RATE, ROUND( ocs.ONLINE_NEW_USERS * 100.0 / NULLIF( ocs.ONLINE_TOTAL_USERS, 0 ), 2 ) AS ONLINE_NEW_RATE, ROUND( ocs.ONLINE_LOYAL_USERS * 100.0 / NULLIF( ocs.ONLINE_TOTAL_USERS, 0 ), 2 ) AS ONLINE_LOYALTY_RATE, ofs.OFFLINE_NEW_USERS, ofs.OFFLINE_REPEAT_USERS, ofs.OFFLINE_TOTAL_USERS, ROUND( ofs.OFFLINE_REPEAT_USERS * 100.0 / NULLIF( ofs.OFFLINE_TOTAL_USERS, 0 ), 2 ) AS OFFLINE_REPEAT_RATE, ROUND( ofs.OFFLINE_NEW_USERS * 100.0 / NULLIF( ofs.OFFLINE_TOTAL_USERS, 0 ), 2 ) AS OFFLINE_NEW_RATE, CASE WHEN LOWER(TRIM(bm.CAPSULE)) IN ( \'embroided shirts\', \'botanical theme\', \'street fc\', \'street fc plus\', \'golf polo theme\', \'photo print\', \'try less denim\', \'printed shirts\', \'luxe\' ) THEN \'YES\' ELSE \'NO\' END AS FOCUS_CAPSULE, ROUND( ( bm.TOTAL_DISCOUNT * 100.0 ) / NULLIF( bm.GROSS_SALES + bm.TOTAL_DISCOUNT, 0 ), 2 ) AS DISCOUNT_PCT, ROUND( 100 - bm.STR_LIFETIME, 2 ) AS STR_REMAINING, CASE WHEN bm.DAYS_ACTIVE <= 30 THEN \'0-30 Days\' WHEN bm.DAYS_ACTIVE <= 60 THEN \'31-60 Days\' WHEN bm.DAYS_ACTIVE <= 90 THEN \'61-90 Days\' WHEN bm.DAYS_ACTIVE <= 120 THEN \'91-120 Days\' WHEN bm.DAYS_ACTIVE <= 180 THEN \'121-180 Days\' ELSE \'180+ Days\' END AS INVENTORY_AGE_BUCKET, CASE WHEN bm.STR_LIFETIME >= 80 THEN \'Excellent\' WHEN bm.STR_LIFETIME >= 60 THEN \'Good\' WHEN bm.STR_LIFETIME >= 40 THEN \'Average\' WHEN bm.STR_LIFETIME >= 20 THEN \'Slow\' ELSE \'Critical\' END AS STR_STATUS FROM business_metrics bm LEFT JOIN online_customer_summary ocs ON LOWER(TRIM(bm.CAPSULE)) = LOWER(TRIM(ocs.CAPSULE)) LEFT JOIN offline_customer_summary ofs ON LOWER(TRIM(bm.CAPSULE)) = LOWER(TRIM(ofs.CAPSULE)) ORDER BY bm.GROSS_SALES DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            